@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Gowun+Dodum&display=swap');
:root{--ink:#28243b;--muted:#8b8798;--pink:#ef6e91;--pink-dark:#d94d75;--cream:#fff8ed;--paper:#fffdf9;--lav:#f0eafa;--gold:#e5ad4f;--line:#eee8e2;--mint:#dff4e7;--shadow:0 16px 42px #43384b12;--font:'DM Sans','Gowun Dodum',sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:var(--font);font-size:14px;min-height:100vh;background-image:radial-gradient(#e9c6a834 1px,transparent 1px);background-size:22px 22px}.page-shell{max-width:1160px;margin:0 auto;padding:0 36px}.topbar{height:74px;border-bottom:1px solid #e8dfd6;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:8px;color:var(--ink);font-size:16px;font-weight:800;letter-spacing:1.9px;text-decoration:none}.brand-mark{width:29px;height:29px;display:grid;place-items:center;color:#fff;background:var(--pink);border-radius:9px;font-size:19px;box-shadow:0 4px 10px #ed75934a}.brand-light{font-weight:500;color:#9993a2}.top-right{display:flex;align-items:center;gap:19px}.edition{color:#9992a0;font-size:11px;letter-spacing:.3px}.language-button{border:1px solid #e6dcd5;background:#fffdf9;border-radius:20px;padding:8px 13px;color:var(--ink);font:700 11px var(--font);cursor:pointer}.language-button span{color:var(--pink);margin-left:5px}.intro-row{display:flex;align-items:center;justify-content:space-between;padding:31px 2px 25px}.eyebrow{font-size:10px;font-weight:800;letter-spacing:1.8px;color:var(--pink);text-transform:uppercase;margin:0 0 7px}.intro-row h1{font-size:34px;line-height:1.15;letter-spacing:-1.4px;margin:0;font-weight:800}.title-accent{color:#dd6482}.subtitle{font-size:13px;color:#817b8a;margin:9px 0 0}.hero-characters{width:300px;height:98px;position:relative;display:flex;align-items:center;justify-content:flex-end;gap:14px;padding-right:24px}.hero-characters:before{content:'';position:absolute;width:208px;height:66px;background:#fff0eb;border-radius:40px;right:5px;bottom:7px;transform:rotate(-4deg)}.character{height:90px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;position:relative;z-index:1}.character-emoji{font-size:42px;line-height:1;filter:drop-shadow(0 5px 3px #ac79812a)}.character-label{margin-top:5px;font-size:10px;font-weight:700;color:#75677a}.character-spark{position:absolute;top:3px;right:-5px;color:var(--gold);font-size:19px}.prince .character-spark{left:-7px;top:11px}.character-heart{position:absolute;right:0;top:0;color:#eb7792;font-size:24px;transform:rotate(12deg)}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 274px;gap:20px;align-items:stretch}.game-card,.side-card{background:var(--paper);border:1px solid #f1e9e1;border-radius:17px;box-shadow:var(--shadow)}.game-card{padding:20px 24px 15px;min-width:0}.game-topline{display:flex;justify-content:space-between;align-items:center;padding-bottom:15px;border-bottom:1px solid var(--line)}.stage-label{display:flex;align-items:center;gap:7px;color:#918a98;font-size:11px;font-weight:600}.stage-label b{color:var(--ink);font-size:12px}.stage-icon{font-size:18px;color:var(--gold)}.lives{display:flex;align-items:center;gap:8px}.lives-label{font-size:9px;color:#a49da7;letter-spacing:.5px}.heart-row{letter-spacing:2px;color:var(--pink);font-size:14px}.heart-row .lost{color:#e9e2e4}.board-heading{display:flex;align-items:center;justify-content:space-between;padding:14px 0 12px}.target-block,.sum-block{display:flex;flex-direction:column;gap:1px}.target-block>span,.sum-block>span{font-size:10px;color:#958e9c}.target-block strong{font-size:30px;line-height:1.15;color:var(--pink);letter-spacing:-1px}.sum-block{align-items:flex-end;min-width:110px}.sum-block strong{display:flex;align-items:baseline;gap:6px;font-size:23px;line-height:1.3}.sum-block small{font-size:10px;color:#a39ba7;font-weight:500;max-width:190px;overflow:hidden;white-space:nowrap}.board-tools{display:flex;gap:6px}.icon-button{width:30px;height:30px;border:1px solid var(--line);border-radius:9px;background:#fff;color:#8f8995;font-size:17px;cursor:pointer;transition:.15s}.icon-button:hover{background:#fff1f4;border-color:#f6cbd6;color:var(--pink)}.block-board{display:grid;grid-template-columns:repeat(5,minmax(40px,1fr));gap:8px;padding:10px;background:#faf5f0;border:1px solid #f0e8e1;border-radius:13px;touch-action:manipulation}.number-block{appearance:none;position:relative;min-height:62px;border:1px solid #f0d7b4;border-radius:10px;background:linear-gradient(145deg,#fff1ce,#ffe3a7);color:#78582f;font:800 21px var(--font);cursor:pointer;box-shadow:0 3px 0 #e7c68e,0 5px 8px #88654412;transition:transform .14s,box-shadow .14s,background .14s;user-select:none;-webkit-tap-highlight-color:transparent}.number-block:nth-child(4n+2){background:linear-gradient(145deg,#ffe4ec,#ffcbd9);border-color:#f2c0ce;color:#a44865;box-shadow:0 3px 0 #e5a7b9,0 5px 8px #88654412}.number-block:nth-child(4n+3){background:linear-gradient(145deg,#e6f4ff,#cce5fb);border-color:#c4dced;color:#4f7597;box-shadow:0 3px 0 #b5d1e4,0 5px 8px #88654412}.number-block:nth-child(4n){background:linear-gradient(145deg,#e9f5e5,#cfeacb);border-color:#c9e2c4;color:#628459;box-shadow:0 3px 0 #b2d2ac,0 5px 8px #88654412}.number-block:hover{transform:translateY(-2px);filter:saturate(1.08)}.number-block.selected{transform:translateY(-2px);outline:3px solid #d96c89;outline-offset:1px;box-shadow:0 4px 0 #e19bae,0 0 0 5px #f7dce4}.number-block.selected:after{content:'✓';position:absolute;top:4px;right:6px;font:700 9px var(--font);color:#fff;background:#d96c89;width:15px;height:15px;border-radius:50%;display:grid;place-items:center}.number-block:disabled{opacity:.52;cursor:default}.action-row{display:flex;align-items:center;gap:12px;padding-top:13px;min-height:59px}.clear-button{flex:none;border:0;background:transparent;color:#9e96a1;font:600 10px var(--font);text-decoration:underline;text-underline-offset:3px;cursor:pointer;padding:7px 0}.status-message{flex:1;margin:0;text-align:center;color:#8d8792;font-size:10px;line-height:1.4}.status-message.success{color:#4b9b69;font-weight:700}.status-message.error{color:#d15375;font-weight:700}.smash-button{display:flex;justify-content:center;align-items:center;gap:18px;flex:none;border:0;border-radius:10px;padding:12px 17px;background:var(--pink);color:#fff;font:700 11px var(--font);box-shadow:0 4px 0 #d45778,0 6px 12px #dc648126;cursor:pointer;transition:.15s}.smash-button:hover{background:var(--pink-dark);transform:translateY(-1px);box-shadow:0 5px 0 #c74469,0 8px 14px #dc64812e}.smash-button:active{transform:translateY(2px);box-shadow:0 2px 0 #c74469}.smash-button:disabled{opacity:.45;cursor:not-allowed;transform:none}.button-arrow{font-size:16px;line-height:10px}.game-footer{display:flex;align-items:center;justify-content:center;gap:18px;color:#aaa3ad;font-size:9px;padding-top:8px;border-top:1px solid #f2ede8}.game-footer kbd{font:600 9px var(--font);border:1px solid #eae3de;background:#fff;border-radius:4px;padding:2px 5px;color:#827b88}.side-column{display:flex;flex-direction:column;gap:12px}.side-card{padding:16px 17px}.side-heading{display:flex;align-items:center;gap:8px;margin-bottom:12px}.side-heading h2{font-size:12px;margin:0;font-weight:800}.side-icon{display:grid;place-items:center;width:25px;height:25px;background:#fff0e8;color:#e3a34c;border-radius:8px;font-size:15px}.how-list{list-style:none;padding:0;margin:0}.how-list li{display:flex;align-items:flex-start;gap:9px;margin:10px 0}.how-list li span{font-size:9px;color:#e5859e;font-weight:800;padding-top:2px}.how-list li p{font-size:10px;color:#716b79;margin:0;line-height:1.5}.tip-box{display:flex;gap:7px;align-items:flex-start;background:#fff8e9;border-radius:8px;padding:9px;margin-top:12px}.tip-box span{font-size:13px}.tip-box p{font-size:9px;color:#8c785b;line-height:1.45;margin:0}.crown-icon{color:#de9e45;background:#fff6dd}.duo-card{padding-bottom:10px}.duo-card .side-heading{margin-bottom:8px}.duo-row{display:flex;align-items:center;gap:9px;padding:8px 0;border-top:1px solid #f4efeb}.mini-avatar{width:32px;height:32px;display:grid;place-items:center;border-radius:10px;font-size:19px}.mini-avatar.pink{background:#fff0f3}.mini-avatar.blue{background:#eef6ff}.duo-row>div{display:flex;flex-direction:column;gap:2px;flex:1}.duo-row b{font-size:10px}.duo-row small{font-size:9px;color:#aaa2ac}.duo-star{color:#e2af61;font-size:14px}.score-strip{display:flex;align-items:center;gap:7px;padding:12px 14px;background:#f1eafa;border-radius:11px;color:#86778f;font-size:10px}.score-strip>span:first-child{color:#ad8cc9;font-size:16px}.score-strip b{margin-left:auto;font-size:15px;letter-spacing:1px;color:#665575}.page-footer{display:flex;justify-content:space-between;color:#a49ca6;font-size:10px;padding:20px 2px 24px}.page-footer span:last-child{color:#cc8492}.modal{position:fixed;inset:0;z-index:10;display:grid;place-items:center;background:#322a3b87;padding:18px;backdrop-filter:blur(4px)}.modal.hidden{display:none}.modal-card{width:min(390px,100%);padding:30px 32px 28px;border-radius:20px;background:#fffdf9;text-align:center;box-shadow:0 20px 70px #17131e42;animation:pop .25s ease-out}.modal-icon{font-size:48px;line-height:1.2}.modal-kicker{font-size:9px;letter-spacing:2px;color:#d97b92;font-weight:800;margin:8px 0}.modal-card h2{font-size:24px;margin:6px 0 8px;letter-spacing:-.7px}.modal-card>p:not(.modal-kicker){font-size:12px;color:#87808d;line-height:1.7;margin:0 auto 20px;max-width:290px}.modal-button{margin:auto;min-width:165px}.shake{animation:shake .28s ease}.burst{animation:burst .3s ease}@keyframes pop{from{transform:scale(.94);opacity:0}to{transform:scale(1);opacity:1}}@keyframes shake{25%{transform:translateX(-4px)}75%{transform:translateX(4px)}}@keyframes burst{to{transform:scale(.65);opacity:0}}
